  // Strip one leading '?' so callers can pass full or bare query strings.
  let str = input;
  if (str[0] === LEADING_Q) {
    str = str.slice(1);
  }

  // Drop the fragment (everything from '#' onward).
  const hashIdx = str.indexOf(FRAGMENT);
  if (hashIdx !== -1) {
    str = str.slice(0, hashIdx);
  }

  // null proto avoids __proto__, constructor, hasOwnProperty pollution.
  const result: Query = Object.create(null) as Query;

  const segments = str.split(AMP);

