    const val = safeDecode(rawVal);

    if (key in result) {
      // Subsequent occurrences of the same key accumulate into an array.
      const prev = result[key];
      if (Array.isArray(prev)) {
        prev.push(val);
      } else {
        result[key] = [prev, val];
      }
    } else {
      result[key] = val;
    }
  }

  return result;
}

