  // The caller has already excluded undefined, null, and arrays.
  if (typeof val === "string") {
    return encodeURIComponent(val);
  }
  if (
    typeof val === "number" ||
    typeof val === "boolean" ||
    typeof val === "bigint"
  ) {
    return encodeURIComponent(String(val));
  }
  // Objects, functions, symbols, nested arrays, etc.
  throw new TypeError(
    `Cannot stringify value of type ${typeof val}`
  );
}

