// Constants ---------------------------------------------------------------

const LEADING_Q: string = "?";
const FRAGMENT: string = "#";
const AMP: string = "&";
const EQ: string = "=";
const PLUS: string = "+";
const SPACE: string = " ";

// Types -------------------------------------------------------------------

export type QueryValue = string | string[];
export type Query = Record<string, QueryValue>;

// safeDecode (called by parseQuery) ---------------------------------------

function safeDecode(raw: string): string {
  // '+' is a space in form-urlencoded data; decode it before % so that
  // a literal '+' encoded as '%2B' is not turned into a space.
  const afterPlus = raw.split(PLUS).join(SPACE);

  try {
    return decodeURIComponent(afterPlus);
  } catch {
    return afterPlus;
  }
}

// parseQuery --------------------------------------------------------------

export function parseQuery(input: string): Query {
  // Accept both a bare query ("a=1") and a full one ("?a=1").
  let str = input;
  if (str[0] === LEADING_Q) {
    str = str.slice(1);
  }

  // A '#' marks the start of a fragment; it is not part of the query.
  const hashIdx = str.indexOf(FRAGMENT);
  if (hashIdx !== -1) {
    str = str.slice(0, hashIdx);
  }

  // A null-prototype object keeps __proto__, constructor, etc. as
  // ordinary own properties without mutating Object.prototype.
  const result = Object.create(null) as Query;

  const segments = str.split(AMP);

  for (const seg of segments) {
    // "&&" and a trailing "&" produce empty segments.
    if (seg === "") {
      continue;
    }

    // Only the first '=' splits key and value; "a=b=c" → a / b=c.
    const eqIdx = seg.indexOf(EQ);
    const rawKey = eqIdx === -1 ? seg : seg.slice(0, eqIdx);
    const rawVal = eqIdx === -1 ? "" : seg.slice(eqIdx + 1);

    const key = safeDecode(rawKey);

    // A key that decodes to the empty string is meaningless.
    if (key === "") {
      continue;
    }

    const val = safeDecode(rawVal);

    // First occurrence stores a bare string; later ones build an array.
    if (!(key in result)) {
      result[key] = val;
      continue;
    }

    const prev = result[key];
    if (!Array.isArray(prev)) {
      result[key] = [prev, val];
      continue;
    }

    prev.push(val);
  }

  return result;
}

// encodeScalar (called by stringifyQuery) ---------------------------------

function encodeScalar(val: unknown): string {
  if (typeof val === "string") {
    return encodeURIComponent(val);
  }

  // number, boolean, and bigint all convert via String().
  if (typeof val === "number") {
    return encodeURIComponent(String(val));
  }
  if (typeof val === "boolean") {
    return encodeURIComponent(String(val));
  }
  if (typeof val === "bigint") {
    return encodeURIComponent(String(val));
  }

  // Objects, functions, symbols, nested arrays, …
  throw new TypeError(
    `Cannot stringify value of type ${typeof val}`,
  );
}

// stringifyQuery ----------------------------------------------------------

export function stringifyQuery(
  query: Record<string, unknown>,
): string {
  const pairs: string[] = [];

  for (const key of Object.keys(query)) {
    const val = query[key];

    // undefined / null → omit the key entirely.
    if (val === undefined) {
      continue;
    }
    if (val === null) {
      continue;
    }

    const encKey = encodeURIComponent(key);

    // Non-array: one pair.
    if (!Array.isArray(val)) {
      pairs.push(`${encKey}=${encodeScalar(val)}`);
      continue;
    }

    // Array: one pair per element, skipping undefined / null.
    for (const elem of val) {
      if (elem === undefined) {
        continue;
      }
      if (elem === null) {
        continue;
      }
      pairs.push(`${encKey}=${encodeScalar(elem)}`);
    }
  }

  return pairs.join(AMP);
}
